// Üretilen dosya: tool/ozgun/uret.py. Fizik · Elektrik devreleri ve elektrik enerjisi hesapları (kolay).
const ozPhysics11Kolay = <(String, String, List<String>, String)>[
  ('Bir telin kesitinden her saniyede 6,25 × 10¹⁸ elektron geçmektedir. Telden geçen akım kaç amperdir? (e = 1,6 × 10⁻¹⁹ C)', '1 A', ['0,1 A', '6,25 A', '10 A'], 'Saniyede geçen yük q = 6,25×10¹⁸ × 1,6×10⁻¹⁹ = 1 C olduğundan akım 1 C/s = 1 A\'dir.'),
  ('Metal bir telde elektronlar A ucundan B ucuna doğru hareket etmektedir. Bu telde geleneksel akım yönü nasıl kabul edilir?', 'B\'den A\'ya doğru', ['A\'dan B\'ye doğru', 'Telin kalınlığına göre değişen bir yönde', 'Yön tanımlanamaz, akım yönsüzdür'], 'Geleneksel akım yönü pozitif yüklerin hareket yönü olarak seçilmiştir; negatif elektronların hareketine ters, yani B\'den A\'ya doğrudur.'),
  ('Bir iletken telin kesit alanı, akım şiddeti değişmeden iki katına çıkarılıyor. Elektronların ortalama sürüklenme hızı nasıl değişir?', 'Yarıya iner', ['İki katına çıkar', 'Değişmez', 'Dört katına çıkar'], 'v = I/(nAe) bağıntısına göre akım ve yük yoğunluğu sabitken alan arttıkça sürüklenme hızı alanla ters orantılı azalır.'),
  ('Bir lambadan ilk 10 saniye boyunca 3 A, sonraki 20 saniye boyunca 1 A akım geçiyor. 30 saniyede lambadan geçen toplam yük kaç coulombdur?', '50 C', ['40 C', '60 C', '150 C'], 'Toplam yük her aşamadaki akım ile sürenin çarpımlarının toplamıdır: 3×10 + 1×20 = 50 C.'),
  ('Kapasitesi 2000 mAh olan bir pil, 250 mA\'lik sabit akım çeken bir cihazı en çok kaç saat çalıştırabilir?', '8 saat', ['4 saat', '0,125 saat', '500 saat'], 'Çalışma süresi, kapasitenin akıma bölünmesiyle bulunur: 2000 mAh / 250 mA = 8 saat.'),
  ('Tamamen boşalmış 4000 mAh\'lik bir pil, sabit 2 A akımla şarj edilirse (kayıplar ihmal) kaç saatte dolar?', '2 saat', ['0,5 saat', '8 saat', '4 saat'], 'Şarj süresi = 4 Ah / 2 A = 2 saattir. Gerçekte kayıplar nedeniyle süre biraz daha uzundur.'),
  ('Bir metal nesnenin üzerine elektrolizle gümüş kaplanıyor. Bu işlem akımın hangi etkisine dayanır?', 'Kimyasal etkisine', ['Isı etkisine', 'Manyetik etkisine', 'Işık ve manyetik etkisine'], 'Elektroliz çözeltisinden geçen akım iyonların elektrotlarda toplanmasına yol açar; kaplama bu kimyasal etkiden yararlanır.'),
  ('Bir devrede geleneksel akım yönü, pilin dışında hangi yönde kabul edilir?', 'Artı uçtan eksi uca doğru', ['Eksi uçtan artı uca doğru', 'Direncin büyük olduğu yönden küçük olduğu yöne', 'Yönü her zaman saat ibresi yönündedir'], 'Geleneksel akım pozitif yük hareketi yönünde tanımlanır; pil dışında artı kutuptan eksi kutba doğrudur.'),
  ('Bir lambadan 5 dakika boyunca sabit 0,3 A akım geçiyor. Bu sürede lambanın kesitinden geçen yük kaç coulombdur?', '90 C', ['1,5 C', '15 C', '900 C'], 'Süre 300 s\'dir; q = I·t = 0,3 × 300 = 90 C bulunur. Dakikayı saniyeye çevirmeyi unutmamak gerekir.'),
  ('1 coulomb yük, kaç tane elektronun yüküne eşdeğerdir? (e = 1,6 × 10⁻¹⁹ C)', '6,25 × 10¹⁸', ['1,6 × 10¹⁹', '6,25 × 10¹⁶', '1,6 × 10⁻¹⁹ adet'], 'Elektron sayısı n = q/e = 1 / 1,6×10⁻¹⁹ = 6,25×10¹⁸\'dir.'),
  ('Bir iletkenin kesitinden geçen yükün zamana göre grafiğinde doğrunun eğimi neyi verir?', 'Anlık akım şiddetini', ['Direnci', 'Devrede harcanan toplam enerjiyi', 'Gücü'], 'I = Δq/Δt olduğundan yük-zaman grafiğinin eğimi akım şiddetidir.'),
  ('Aynı maddeden yapılmış bir telin uzunluğu iki katına çıkarılırken kesit alanı değiştirilmiyor. Telin direnci nasıl değişir?', 'İki katına çıkar', ['Yarıya düşer', 'Dört katına çıkar', 'Değişmez'], 'R = ρL/A bağıntısına göre direnç uzunlukla doğru orantılıdır; uzunluk iki katına çıkınca direnç de iki katına çıkar.'),
  ('Bir telin yarıçapı iki katına çıkarılır, uzunluğu ve maddesi aynı kalır. Telin direnci ilk değerinin kaç katı olur?', '1/4', ['1/2', '1/16', '4'], 'Kesit alanı yarıçapın karesiyle orantılıdır; yarıçap iki katına çıkınca alan 4 katına çıkar ve R = ρL/A dörtte birine düşer.'),
  ('Bir tel için ölçülen özdirenç değeri aşağıdakilerden hangisine bağlıdır?', 'Telin maddesine ve sıcaklığına', ['Telin uzunluğuna', 'Telin kesit alanına', 'Telden geçen akıma ve uygulanan gerilime'], 'Özdirenç maddeye özgü bir niceliktir ve sıcaklıkla değişir; telin boyutlarından ve uygulanan gerilimden bağımsızdır.'),
  ('Bir direncin uçlarına bağlanan gerilim–akım doğrusu (0 V, 0 A) ve (6 V, 0,4 A) noktalarından geçmektedir. Direncin değeri kaç ohmdur?', '15 Ω', ['2,4 Ω', '24 Ω', '1,5 Ω'], 'Doğrunun eğimi 1/R\'dir (I–V çiziminde) ya da V/I = 6/0,4 = 15 Ω\'dur.'),
  ('Aşağıdaki devre elemanlarından hangisi Ohm yasasına uymayan (omik olmayan) bir elemandır?', 'Diyot', ['Karbon direnç', 'Sabit sıcaklıktaki nikel-krom tel', 'Bakır tel'], 'Diyodun akım–gerilim ilişkisi doğrusal değildir; belirli bir eşik geriliminden sonra akım hızla artar. Diğerleri sabit sıcaklıkta omiktir.'),
  ('Etiketinde 1 kΩ ve ±%10 tolerans yazan bir direncin gerçek değeri hangi aralıkta olabilir?', '900 Ω ile 1100 Ω arasında', ['990 Ω ile 1010 Ω arasında', '100 Ω ile 1100 Ω arasında yer alır', '800 Ω ile 1200 Ω arasında'], '%10 tolerans, 1000 Ω\'un ±100 Ω\'luk sapmasına izin verir; değer 900–1100 Ω aralığındadır.'),
  ('Bir iletkenin direnci 4 Ω ise elektriksel iletkenliği (kondüktansı) kaç siemenstir?', '0,25 S', ['4 S', '0,4 S', '0,0625 S'], 'İletkenlik direncin çarpma tersidir: G = 1/R = 1/4 = 0,25 S\'dir.'),
  ('Bir karbon direncin üzerinde 2,2 kΩ yazıyor. Uçlarına 11 V uygulandığında geçmesi beklenen akım kaç miliamperdir?', '5 mA', ['0,5 mA', '50 mA', '2,42 mA'], 'I = V/R = 11 / 2200 = 5×10⁻³ A = 5 mA\'dir.'),
  ('12 V\'luk bir pile 2 Ω, 4 Ω ve 6 Ω\'luk üç direnç seri bağlanmıştır (pilin iç direnci ihmal ediliyor). 4 Ω\'luk direncin uçları arasındaki gerilim kaç volttur?', '4 V', ['2 V', '6 V', '12 V'], 'Eşdeğer direnç 12 Ω, akım I = 12/12 = 1 A\'dir. 4 Ω\'luk direncin gerilimi V = 1 × 4 = 4 V\'tur.'),
  ('Seri bağlı eski tip bir yılbaşı ışık dizisinde tek bir lamba yuvasından çıkarılırsa diğer lambalara ne olur?', 'Tüm lambalar söner, çünkü devre açılır', ['Bütün lambalar daha parlak yanar', 'Yalnız çıkarılan lambanın yanındakiler söner', 'Diğer lambalar etkilenmeden yanmaya devam eder'], 'Seri devrede tek yol vardır. Bir eleman çıkarılırsa devre kesilir ve akım hiçbir lambadan geçmez.'),
  ('9 V\'luk bir kaynağa seri bağlanan 1 kΩ ve 2 kΩ\'luk dirençlerden oluşan gerilim bölücüde 2 kΩ\'luk direncin uçları arasındaki gerilim kaç volttur?', '6 V', ['3 V', '4,5 V', '9 V'], 'Gerilim dirençlerle orantılı bölünür: V₂ = 9 × 2/(1+2) = 6 V\'tur.'),
  ('3 Ω\'luk bir direnç ile bilinmeyen bir R direnci seri bağlanıp 18 V\'luk kaynağa bağlandığında devreden 2 A akım geçiyor. R kaç ohmdur?', '6 Ω', ['9 Ω', '3 Ω', '12 Ω'], 'Toplam direnç 18/2 = 9 Ω\'dur. R = 9 − 3 = 6 Ω bulunur.'),
  ('12 V\'luk bir kaynağa paralel bağlı 4 Ω ve 6 Ω\'luk dirençlerden kaynaktan çekilen toplam akım kaç amperdir?', '5 A', ['1,2 A', '2,5 A', '10 A'], 'Kollardan geçen akımlar 12/4 = 3 A ve 12/6 = 2 A\'dir; toplam akım 5 A\'dir.'),
  ('Sabit gerilimli bir kaynağa paralel bağlı dirençlerden oluşan devreye bir direnç daha paralel eklenirse ana koldaki akım ve eşdeğer direnç nasıl değişir?', 'Akım artar, eşdeğer direnç azalır', ['Akım azalır, eşdeğer direnç artar, kaynak gerilimi düşer', 'Akım artar, eşdeğer direnç artar', 'İkisi de değişmez'], 'Yeni bir paralel kol akım için ek yol açar; eşdeğer direnç azalır ve I = V/R_eş olduğundan ana akım artar.'),
  ('Aynı kaynağa paralel bağlı 5 Ω, 10 Ω ve 20 Ω\'luk dirençlerden hangisi en çok ısı açığa çıkarır?', '5 Ω\'luk direnç', ['10 Ω\'luk direnç', '20 Ω\'luk direnç', 'Üçü de eşit ısı açığa çıkarır'], 'Paralel kollarda gerilim eşittir ve P = V²/R\'dir; en küçük direnç en büyük gücü harcar ve en çok ısınır.'),
  ('Biri 20 Ω, diğeri 5 Ω olan iki direnç paralel bağlanıp bir kaynağa bağlandığında 20 Ω\'luk dirençten geçen akımın, 5 Ω\'luk dirençten geçen akıma oranı kaçtır?', '1/4', ['1/16', '1/2', '2'], 'Paralel kollarda gerilim aynıdır; akım dirençle ters orantılıdır: I₂₀/I₅ = 5/20 = 1/4.'),
  ('İki özdeş 2 Ω\'luk direncin paralel bağlanmasıyla oluşan grup, 3 Ω ve 6 Ω\'luk dirençlerin paralel bağlanmasıyla oluşan grupla seri bağlanıyor. Eşdeğer direnç kaç ohmdur?', '3 Ω', ['13 Ω', '1,5 Ω', '4,5 Ω'], 'İlk grup 1 Ω, ikinci grup (3·6)/(3+6) = 2 Ω\'dur. Seri toplam 1 + 2 = 3 Ω olur.'),
  ('Bir üretece bağlı lambaya paralel olarak kalın bir iletken tel bağlanırsa lamba ve kaynaktan çekilen akım için ne söylenebilir?', 'Lamba söner, kaynaktan çekilen akım artar', ['Lamba daha parlak yanar, çekilen akım azalır', 'Lamba aynı parlaklıkta yanar, çekilen akım değişmez', 'Lamba söner, çekilen akım sıfıra düşer'], 'Tel lambaya göre çok düşük dirençli bir yoldur; akım telden geçer, lambanın uçlarındaki gerilim sıfıra yaklaşır ve toplam direnç düştüğü için çekilen akım artar.'),
  ('Wheatstone köprüsünde dengeye ulaşıldığında P = 3 Ω, Q = 6 Ω ve R = 4 Ω\'dur. P ve Q bir kolda, R ve S diğer kolda ise bilinmeyen S direnci kaç ohmdur?', '8 Ω', ['2 Ω', '4,5 Ω', '12 Ω'], 'Denge koşulu P/Q = R/S\'dir. 3/6 = 4/S olduğundan S = 8 Ω\'dur.'),
  ('2 Ω, 3 Ω ve 6 Ω\'luk dirençler birbirine paralel bağlanmıştır. Bu gruba 1 Ω\'luk bir direnç seri eklenirse toplam direnç kaç ohm olur?', '2 Ω', ['12 Ω', '1 Ω', '7 Ω'], 'Paralel grup 1/R = 1/2 + 1/3 + 1/6 = 1 olduğundan 1 Ω\'dur. 1 Ω seri eklenince toplam 2 Ω olur.'),
  ('Seri bağlı iki dirençten birine paralel bir direnç eklenirse devrenin toplam direnci ve ana akım nasıl değişir? (Gerilim sabit)', 'Toplam direnç azalır, ana akım artar', ['Toplam direnç artar, ana akım azalır', 'Toplam direnç azalır, ana akım azalır', 'Toplam direnç artar, ana akım artar'], 'Bir dirence paralel kol eklemek o grubun direncini düşürür; toplam direnç azalır ve I = V/R_eş arttığı için ana akım artar.'),
  ('Emk\'sı 1,5 V ve iç direnci 0,3 Ω olan bir pilden 2 A akım çekilirken pilin uçları arasındaki gerilim kaç volttur?', '0,9 V', ['1,5 V', '1,2 V', '0,45 V'], 'Uç gerilimi V = ε − I·r = 1,5 − 2 × 0,3 = 0,9 V\'tur.'),
  ('Dört adet 1,5 V\'luk pil seri bağlanırken yanlışlıkla biri ters yerleştirilmiştir. Bileşimin net emk\'sı kaç volttur?', '3 V', ['6 V', '4,5 V', '0 V'], 'Üç pil ileri, biri geri yönde olduğundan net emk 3×1,5 − 1,5 = 3 V\'tur.'),
  ('Emk\'sı 4,5 V, iç direnci 1,5 Ω olan bir pile 3 Ω\'luk bir ampul bağlanıyor. Ampulün uçlarındaki gerilim kaç volttur?', '3 V', ['4,5 V', '1,5 V', '2,25 V'], 'Akım I = 4,5/(3+1,5) = 1 A\'dir. Ampulün gerilimi V = 1 × 3 = 3 V\'tur.'),
  ('Bir pil 3 C\'luk yükü devrede dolaştırırken kimyasal enerjisinden 27 J\'ü elektrik enerjisine dönüştürüyor. Pilin emk\'sı kaç volttur?', '9 V', ['81 V', '0,11 V', '24 V'], 'Emk, birim yük başına dönüştürülen enerjidir: ε = W/q = 27/3 = 9 V.'),
  ('Emk\'sı 12 V olan bir üretecin uç gerilimi yük altında 9,6 V ölçülüyor. Üretecin verimi yüzde kaçtır?', '%80', ['%20', '%96', '%125'], 'Verim, uç geriliminin emk\'ya oranıdır: 9,6/12 = 0,8 yani %80\'dir.'),
  ('Bir düğüm noktasına 5 A ve 3 A\'lik iki kol akım getirmekte, düğümden 2 A\'lik bir kol ve bir başka kol akım götürmektedir. Dördüncü koldaki akım kaç amperdir ve yönü nedir?', '6 A, düğümden dışarı doğru', ['6 A, düğüme doğru', '10 A, düğümden dışarı doğru', '0 A'], 'Düğüm kuralına göre giren akımlar çıkanlara eşittir: 5 + 3 = 2 + I olduğundan I = 6 A ve düğümden dışarı doğrudur.'),
  ('Kirchhoff\'un ilmek kuralında, ilmek yönünde ilerlerken bir pilin eksi kutbundan artı kutbuna geçiliyorsa denkleme bu pil için nasıl bir terim yazılır?', '+ε', ['−ε', '+ε/r', '0'], 'İlmek yönünde potansiyelin yükseldiği geçişlerde terim pozitif alınır; eksi uçtan artı uca geçişte potansiyel ε kadar artar.'),
  ('Bir düğüme giren akımlar 3 A ve 4 A, düğümden çıkan akımlar 5 A ve I\'dır. I kaç amperdir?', '2 A', ['12 A', '1 A', '7 A'], 'Giren toplam 7 A, çıkan toplam 5 + I olmalıdır; bu durumda I = 2 A bulunur.'),
